local wukong = require(game.ReplicatedStorage.Packages.WuKong)
local parse = require(script.Parent.Parent.parse)
local formatTableModule = require(script.Parent.Parent.formatTable)
local formatTable = formatTableModule.formatTable

local WKData = {}
WKData.__index = WKData

function WKData.new(item, parent)
	local self = {}
	setmetatable(self, WKData)

	self._item = item
	self._parent = parent
	self._children = {}
	self._type = nil
	self._abilities = nil
	self._cacheTable = {}
	self._canCount = nil
	self._sortTime = tick()
	return self
end

function WKData:GetPath()
	if self._type == "Element" or self._type == "PropertyItem" then
		return self._parent:GetPath() .. "/[pc]"
	end

	if self._type == "Slot" and self._parent._type == "PropertyItem" then
		local path = self._item:getPath()
		if string.sub(path, 1, 1) ~= "/" then
			path = "/" .. path
		end
		path = self._parent:GetPath() .. path
		-- local displayPath = path == "/" and "root" or path
		local displayPath = path
		return displayPath, path
	end

	local path = self._item:getPath()
	if string.sub(path, 1, 1) ~= "/" then
		path = "/" .. path
	end
	-- local displayPath = path == "/" and "root" or path
	local displayPath = path
	return displayPath, path
end

function WKData:GetId()
	return self._item:getId()
end

function WKData:GetName()
	return self._item:getName()
end

function WKData:GetType()
	return self._type
end

function WKData:GetChildren()
	return self._children
end

function findAllNumbers(str)
	local numbers = {}
	for number in string.gmatch(str, "(%d+)") do
		table.insert(numbers, number)
	end
	return numbers
end

function WKData:GetSortedChildren()
	if not self._sortedChildren or self._sortTime + 0.2 < tick() then
		local temp = {}
		self._sortTime = tick()
		self._sortedChildren = {}
		for i, v in pairs(self._children) do
			local id = v:GetId()
			local numbers = findAllNumbers(id)
			-- 如果v._item._isActive等于true order越小
			-- id 是中文，英文，数字组合
			-- 生成排序
			local order = v._item._isActive and -1000000 or 0

			-- 生成排序
			-- 处理非数字部分
			local nonNumericPart = id:gsub("%d+", "")
			local nonNumOrder = 0
			for i = 1, #nonNumericPart do
				nonNumOrder = nonNumOrder + string.byte(nonNumericPart:sub(i, i))
			end
			order += (nonNumOrder * 10 ^ 3)
			-- 处理数字部分
			if #numbers > 0 then
				local numOrder = 0
				for i, num in ipairs(numbers) do
					numOrder = numOrder + tonumber(num) * (10 ^ (3 - i * 3))
				end
				order += numOrder
			end

			-- 将排序结果添加到临时表中
			table.insert(temp, {
				num = order,
				data = v,
			})
			continue
		end
		table.sort(temp, function(a, b)
			return a.num > b.num
		end)
		for j, k in ipairs(temp) do
			table.insert(self._sortedChildren, 1, k.data)
		end
	end
	return self._sortedChildren
end

function WKData:GetParent()
	return self._parent
end

function WKData:GetItem()
	return self._item
end

function WKData:CheckCanCount()
	if self._canCount == nil then
		self._canCount = false
		local ability = self:GetAbilities()
		local queries = ability.queries
		for i, v in pairs(queries) do
			if v.Name == "获取计算属性值" then
				self._canCount = true
				break
			end
		end
	end
	return self._canCount
end

function WKData:GetCacheValue(name, timeout)
	if not self._cacheTable[name] then
		return nil
	end

	if self._cacheTable[name].t + timeout < tick() then
		return nil
	end
	return self._cacheTable[name].v
end

function WKData:SetCacheValue(name, value)
	self._cacheTable[name] = {
		t = tick(),
		v = value,
	}
end

function WKData:GetValue()
	if self:CheckCanCount() then
		local cache = self:GetCacheValue("获取计算属性值", 0.1)
		if not cache then
			local path = self._item:getPath()
			if string.sub(path, 1, 1) ~= "/" then
				path = "/" .. path
			end
			path = path .. "?获取计算属性值"
			local id = self:GetId()
			local suc, res = pcall(function()
				return wukong:ExecuteQuery(path, id)
			end)
			if suc then
				self:SetCacheValue("获取计算属性值", res)
				return res
			end
		else
			return cache
		end
	end
	return nil
end

function WKData:GetCount()
	return (self._item and (self._item._type == 1 or self._item._type == 2)) and self._item:getCount() or nil
end

function WKData:GetElementType()
	local first = self._children[1]
	if first then
		if first._type == "PropertyItem" then
			return "PropertyItem"
		elseif first._type == "Element" then
			return "Element"
		end
	end
	return nil
end

local function getParameters(pluginMethod: {})
	local methodName = pluginMethod.Name
	local methodInfo = pluginMethod.MethodInfo

	-- 是不是查询观察者
	local isQueryObserver = pluginMethod.IsQueryObserver

	-- 参数中,第一个是容器, 忽略之,然后截取后续的parameterNames的长度,就是参数的个数
	local parameterTypes = _G.wdm.Runtime.LuaMethodHelper.GetMethodParamsTypes(methodInfo)
	-- 参数名称(通过Attribue获取)
	local parameterNames = pluginMethod.ParameterNames
	local t = {}
	for i = 1, #parameterNames do
		table.insert(t, parameterTypes[2 + i - 1].__name__)
	end

	return parameterNames, t
end

function WKData:GetAbilities()
	if not self._abilities then
		local actions = {}
		local queries = {}
		local validators = {}

		pcall(function()
			if self._type == "Slot" or self._type == "Container" or self._type == "PropertyItem" then
				if self._type == "PropertyItem" then
					actions = _G.wdm.WuKong.Core.PluginsMethodExtension.GetPluginActions(self._item.PropertyContainer)
					queries = _G.wdm.WuKong.Core.PluginsMethodExtension.GetPluginQueries(self._item.PropertyContainer)
					validators =
						_G.wdm.WuKong.Core.PluginsMethodExtension.GetPluginValidators(self._item.PropertyContainer)
					--actions = _G.wdm.WuKong.Core.PluginsMethodExtension.GetPluginActions(self._item)
					--queries = _G.wdm.WuKong.Core.PluginsMethodExtension.GetPluginQueries(self._item)
					--validators = _G.wdm.WuKong.Core.PluginsMethodExtension.GetPluginValidators(self._item)
				else
					actions = _G.wdm.WuKong.Core.PluginsMethodExtension.GetPluginActions(self._item)
					queries = _G.wdm.WuKong.Core.PluginsMethodExtension.GetPluginQueries(self._item)
					validators = _G.wdm.WuKong.Core.PluginsMethodExtension.GetPluginValidators(self._item)
				end
			end
		end)

		self._abilities = {
			actions = actions,
			queries = queries,
			validators = validators,
		}
	end
	return self._abilities
end

function WKData:GetParameters(ability)
	return getParameters(ability)
end

local filters = {
	Cfg = true,
	Parent = true,
	Tables = true,
}

function getTable(t)
	local function loop(t, temp)
		-- 深拷贝
		for i, v in pairs(t) do
			if not filters[i] then
				if typeof(v) == "table" then
					temp[i] = {}
					loop(v, temp[i])
				else
					temp[i] = v
				end
			end
		end
	end
	local temp = {}
	loop(t, temp)
	return temp
end

function WKData:Execute(operation, path, inputs)
	local suc, res
	local t = operation.t
	local ability = operation.i.object
	local _, paraTypes = getParameters(ability)
	local paras = parse(paraTypes, inputs)
	if wukong["Execute" .. t] then
		suc, res = pcall(function()
			return wukong["Execute" .. t](wukong, path, table.unpack(paras))
		end)
	end
	local restable = nil
	if res ~= nil then
		if suc then
			if t == "Validate" then
				res = res:ToString()
			else
				if typeof(res) == "table" and not res.message then
					local temp = {}
					-- todo 复杂table无法format
					for i, v in pairs(res) do
						temp[i] = tostring(v)
					end
					restable = getTable(res)
					res = formatTable(temp, "Long"):gsub("^%s*(.-)%s*$", "%1")
				else
					res = tostring(res)
				end
			end
		else
			res = res.message
		end
	end
	local info = "Execute" .. t
	local args = ""
	args = args .. '"' .. path .. '"'
	for i, v in pairs(paras) do
		local paraType = paraTypes[i]
		if v == "__null__" then
			paraType = "System.String"
		end
		if paraType == "System.String[]" then
			local temp = {}
			for j, k in pairs(v) do
				temp[j] = '"' .. k .. '"'
			end
			args = args .. ", " .. "{" .. table.concat(temp, ", ") .. "}"
		elseif paraType == "System.String" then
			args = args .. ", " .. '"' .. v .. '"'
		else
			args = args .. ", " .. tostring(v)
		end
	end
	info = info .. "\n\n" .. args .. "\n\n" .. "********" .. (suc and "Success" or "Error") .. "********" .. "\n"
	-- info = info .. "\n" .. "Args: " .. "\"" .. path .. "\"" .. "," .. inputs
	-- print(info)
	return suc, res, info, restable
end

local function getChildCount(wkdata)
	return #wkdata._children
end
local function getPropertyItemCount(wkdata)
	if wkdata._item._element and #wkdata._children == 0 then
		local element = wkdata._item:getElement()
		if element then
			local d = WKData.new(element, wkdata)
			table.insert(wkdata._children, d)
			if wukong:IsPropertyItem(element) then
				d._type = "PropertyItem"
			end
		end
	elseif not wkdata._item._element and #wkdata._children > 0 then
		table.clear(wkdata._children)
	end
	if #wkdata._children > 0 and wkdata._children[1]._item then
		if wkdata._children[1]._item._type == 1 or wkdata._children[1]._item._type == 2 then
			return wkdata._children[1]._item._count
		else
			return #wkdata._children
		end
	else
		return 0
	end
end

local function getCount(wkdata)
	return wkdata._children[1]:GetCount()
end

local function getSlotChildCount(wkdata)
	return #wkdata._children
end

function WKData:QueryList()
	local sortedChildren = self:GetSortedChildren()
	local list = {}
	local third = nil
	local substr = ""

	list[1] = { "Id", "Name                  ", "Child        " }
	third = getChildCount
	if self._type2 == "ElementContainer" then
		if self._item.ElementType == 1 then
			list[1] = { "Id", "Name                  ", "Value        " }
			third = getCount
			--value
		elseif self._item.ElementType == 2 then
			list[1] = { "Id", "Name                  ", "Item         " }
			third = getPropertyItemCount
			--propertyItem
		end
	end
	if self._type == "Slot" then
		list[1] = { "Id", "Name                  ", "Child        " }
		third = getSlotChildCount
	end
	for i, v in pairs(sortedChildren) do
		if self._type == "Slot" and v._type == "Element" then
			continue
		end
		local name = v._item.Id
		-- if not name then
		-- 	continue
		-- end
		local count = third(v)
		if count == 0 then
			substr = ""
		end
		if self._item.ElementType == 2 then
			pcall(function()
				if v._item._isActive then
					i = i .. " ⚡"
				end
			end)
			if v._children and #v._children > 0 then
				substr = "   🚩"
			end
		elseif v._type == "PropertyItem" then
			pcall(function()
				if v._item._isActive then
					i = i .. " ⚡"
				end
			end)
			substr = "   🚩"
			name = ""
		elseif v._type == "Slot" then
			if v._children and #v._children > 0 then
				if v._children[1]._type == "Element" and v._children[1]._item._type == 3 then
					pcall(function()
						if v._item._isActive then
							i = i .. " ⚡"
						end
					end)
					third = function()
						return ""
					end
					list[1] = { "Id", "Name                  ", "Count        " }
					pcall(function()
						substr = v._children[1]._item:getCount()
					end)
				end
			end
		end
		local node = {
			i,
			name,
			third(v) .. substr,
		}
		table.insert(list, node)
	end
	return list
end

function WKData:GetChildrenFromSorted(idx)
	idx = string.gsub(idx, " ⚡", "") - 0
	local child = self._sortedChildren[idx]
	if (self._item.ElementType == 2 or self._item.ElementType == 3) and #child._children == 0 then
		return nil
	end
	if child._type == "PropertyItem" then
		return child
	elseif child._type == "Element" then
		return nil
	end
	return child
end

return WKData
